# LINUXQUEST — SCRIPT BUILDER & PARSER TEST SUITE

import unittest

class TestScriptBuilderValidation(unittest.TestCase):
    def test_script_syntax_case_1(self):
        code = '#!/bin/bash\nset -euo pipefail\necho task_1'
        self.assertTrue(code.startswith('#!'))
        self.assertIn('set -euo pipefail', code)

